Lemma LIT_OK : forall f, literal_spec L (PCf f) (LSf f) (LGf f) (LTXTf f) (LLENf f).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$f;R+6-6RN$b;R+6!7'aX/SCFG_P;/L;!1'aY#1!1'aZ#1!1'a[#1!1'a\#1!1'b0#1#12/TRUE_OK;/FALSE_OK;").
Qed.
Definition VSCR := EVNN.VSCR.

Theorem visit_bool_nested_ok : forall (bb : bool) (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  g_es g = c0 :: r0 ->
  PML.cps_heap L HI PC_VISIT_BOOL r sp VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r VSCR /\ PML.a0 R V /\ PML.a1 R (PML.b2z bb) /\ enc_inv M V S2 g /\ ev_guard (g_es g) (EvBool bb) /\ PML.img_ro M /\ PML.lits_ok M /\
                ecredit L cr g kx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PML.a0 R' 1 /\ enc_inv M' V S2 g' /\ g_es g' = estep (g_es g) (EvBool bb) /\ pay_ok (EvBool bb) pay /\ g_len g' = g_len g + ev_ind (g_es g) (EvBool bb) + pay /\
